#!/usr/bin/env python3
"""v2-30: fixes from a live phone-width check: the bottom bar follows the light theme; five small buttons get a 44px touch size.
Run from the nutrismart folder AFTER v2-26..v2-29. Safe to run twice."""
import base64, os, sys
if not os.path.isdir('src') or not os.path.isdir('functions'):
    sys.exit('Run this inside the nutrismart project folder (cd ~/Downloads/nutrismart).')
def rd(p): return open(p, encoding='utf8').read()
def wr(p, s): open(p, 'w', encoding='utf8').write(s)
def sub(p, old, new, marker):
    s = rd(p)
    if marker in s: print('already applied:', p, '-', marker[:30]); return
    if old not in s: sys.exit(f'Cannot find the expected text in {p}. Stop and send this message to Claude.')
    wr(p, s.replace(old, new, 1)); print('updated', p)
if not os.path.exists('src/styles/newdesign.css'): sys.exit('Run v2-26 to v2-29 first.')
wr('src/styles/newdesign.css', base64.b64decode('').decode('utf8')); print('updated src/styles/newdesign.css')
D='src/components/DashboardLogging.tsx'
sub(D, 'w-8 h-8 rounded-full bg-[#2C2C2E] text-[#7DD3FC]', 'w-11 h-11 rounded-full bg-[#2C2C2E] text-[#7DD3FC]', 'w-11 h-11 rounded-full bg-[#2C2C2E] text-[#7DD3FC]')
sub(D, 'w-8 h-8 rounded-full bg-[#7DD3FC]/20', 'w-11 h-11 rounded-full bg-[#7DD3FC]/20', 'w-11 h-11 rounded-full bg-[#7DD3FC]/20')
sub(D, 'className="flex items-center gap-3 flex-1 min-w-0 text-left"', 'className="flex items-center gap-3 flex-1 min-w-0 min-h-[44px] text-left"', 'flex-1 min-w-0 min-h-[44px] text-left')
sub(D, 'className={`mt-0.5 min-h-[32px] min-w-[44px] px-2 rounded-lg', 'className={`mt-0.5 min-h-[44px] min-w-[44px] px-2 rounded-lg', 'mt-0.5 min-h-[44px] min-w-[44px]')
sub('src/components/ProfileCompletion.tsx', 'aria-label="Hide for a week" className="text-[#8E8E93] text-lg px-1"', 'aria-label="Hide for a week" className="text-[#8E8E93] text-lg px-1 min-w-[44px] min-h-[44px]"', 'min-w-[44px] min-h-[44px]')
sub('src/components/FlexibleMealCard.tsx', 'underline min-h-[32px]">Plan one', 'underline min-h-[44px]">Plan one', 'min-h-[44px]">Plan one')
t='src/tests/ui26/newdesign.test.ts'
s=rd(t)
if 'fixes from the live phone-width check' in s: print('already applied:', t)
else: wr(t, s.rstrip('\n')+'\n'+base64.b64decode('').decode('utf8')); print('updated', t)
print('\nDone. Next: git add -A, commit, push.')
